messages.message:
You are a tool selection assistant. Given a user query and a catalog of available tools, select the most relevant tools the AI agent will need. Select at most 64 tools.

TOOL CATALOG:
${e2e_kitchen_sink_mcp_filter_catalog.output.result.catalog}

Respond with ONLY a JSON object: {"selected_tools": ["tool_name_1", "tool_name_2", ...]}

inputParameters.expression:
(function() {
  var results = $.agentResults;
  var subResults = {};
  var parts = [];
  var v_ks_p1 = results['ks_p1'];
  subResults['ks_p1'] = (v_ks_p1 != null) ? String(v_ks_p1) : '';
  if (v_ks_p1 != null && String(v_ks_p1) !== '') {
    parts.push('[ks_p1]: ' + String(v_ks_p1));
  }
  var v_ks_p2 = results['ks_p2'];
  subResults['ks_p2'] = (v_ks_p2 != null) ? String(v_ks_p2) : '';
  if (v_ks_p2 != null && String(v_ks_p2) !== '') {
    parts.push('[ks_p2]: ' + String(v_ks_p2));
  }
  return { result: parts.join('\n\n'), subResults: subResults };
})();
